    h,w=len(grid),len(grid[0]); out=[[0]*w for _ in range(h)]
    wall=next((r for r,row in enumerate(grid) if all(v==2 for v in row)),h)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==2: out[r][c]=2
            elif v==4:
                nr=r+1 if r<wall else r+1
                if nr>=h: nr=r
                out[nr][c]=4
                if nr==wall-1:
                    for d in range(1,nr+1):
                        for cc in (c-d,c+d):
                            if 0<=cc<w: out[nr-d][cc]=4
    return out
